#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\n🔍 GZIP 格式验证脚本\n\n用于验证新的 .gz 文件格式是否正确生成、压缩和解压\n支持：\n  - 生成测试 GZIP 文件\n  - 验证压缩比\n  - 测试解压功能\n  - 与标准工具兼容性\n\"\"\"\n\nimport gzip\nimport os\nimport sys\nfrom pathlib import Path\nfrom datetime import datetime\n\n\ndef print_header(title):\n    \"\"\"打印标题\"\"\"\n    print(f\"\\n{'='*60}\")\n    print(f\"  {title}\")\n    print(f\"{'='*60}\")\n\n\ndef print_success(message):\n    \"\"\"打印成功信息\"\"\"\n    print(f\"✅ {message}\")\n\n\ndef print_error(message):\n    \"\"\"打印错误信息\"\"\"\n    print(f\"❌ {message}\")\n\n\ndef print_info(message):\n    \"\"\"打印信息\"\"\"\n    print(f\"ℹ️  {message}\")\n\n\ndef test_gzip_compress():\n    \"\"\"测试 GZIP 压缩功能\"\"\"\n    print_header(\"测试 1: GZIP 压缩功能\")\n    \n    # 创建测试数据\n    test_data = b\"Hello, World! This is a test for GZIP compression.\" * 100\n    print_info(f\"原始数据大小: {len(test_data)} 字节\")\n    \n    try:\n        # 压缩数据\n        compressed = gzip.compress(test_data)\n        print_success(f\"压缩成功\")\n        print_info(f\"压缩后大小: {len(compressed)} 字节\")\n        print_info(f\"压缩比: {100 - (len(compressed) / len(test_data) * 100):.2f}%\")\n        \n        # 解压数据\n        decompressed = gzip.decompress(compressed)\n        print_success(f\"解压成功\")\n        \n        # 验证数据完整性\n        if decompressed == test_data:\n            print_success(f\"数据完整性验证: 原始数据与解压数据一致\")\n            return True\n        else:\n            print_error(f\"数据不匹配!\")\n            return False\n    except Exception as e:\n        print_error(f\"错误: {str(e)}\")\n        return False\n\n\ndef test_huffman_simulation():\n    \"\"\"模拟 Huffman 编码后的 GZIP 压缩\"\"\"\n    print_header(\"测试 2: 模拟 Huffman 编码 + GZIP 压缩\")\n    \n    try:\n        # 创建模拟的 Huffman 编码比特流\n        # 假设这是编码后的二进制数据\n        huffman_bits = \"110100110101011010\" * 100  # 模拟编码的比特\n        \n        # 转换为字节（模拟后端的编码逻辑）\n        huffman_bytes = bytes(\n            int(huffman_bits[i:i+8], 2) \n            for i in range(0, len(huffman_bits), 8)\n        )\n        print_info(f\"Huffman 编码字节数: {len(huffman_bytes)} 字节\")\n        \n        # 使用 GZIP 压缩\n        compressed = gzip.compress(huffman_bytes)\n        print_success(f\"GZIP 压缩成功\")\n        print_info(f\"压缩后大小: {len(compressed)} 字节\")\n        print_info(f\"总体压缩比: {100 - (len(compressed) / len(huffman_bytes) * 100):.2f}%\")\n        \n        # 测试解压\n        decompressed = gzip.decompress(compressed)\n        if decompressed == huffman_bytes:\n            print_success(f\"解压验证: 数据一致\")\n            return True\n        else:\n            print_error(f\"解压数据不匹配\")\n            return False\n    except Exception as e:\n        print_error(f\"错误: {str(e)}\")\n        return False\n\n\ndef test_file_operations():\n    \"\"\"测试文件保存和读取\"\"\"\n    print_header(\"测试 3: 文件保存和读取\")\n    \n    test_dir = Path(\"test_gzip\")\n    test_dir.mkdir(exist_ok=True)\n    \n    try:\n        # 创建测试数据\n        test_data = b\"Sample compression test data\" * 50\n        timestamp = datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n        filename = f\"{timestamp}_compressed.gz\"\n        filepath = test_dir / filename\n        \n        print_info(f\"创建测试文件: {filepath}\")\n        \n        # 压缩并保存\n        compressed = gzip.compress(test_data)\n        with open(filepath, \"wb\") as f:\n            f.write(compressed)\n        print_success(f\"文件保存成功\")\n        \n        # 检查文件大小\n        file_size = os.path.getsize(filepath)\n        original_size = len(test_data)\n        print_info(f\"原始大小: {original_size} 字节\")\n        print_info(f\"文件大小: {file_size} 字节\")\n        \n        # 读取和解压\n        with gzip.open(filepath, \"rb\") as f:\n            decompressed = f.read()\n        print_success(f\"文件读取和解压成功\")\n        \n        # 验证数据\n        if decompressed == test_data:\n            print_success(f\"数据验证: 原始与解压数据一致\")\n            return True, filepath\n        else:\n            print_error(f\"数据验证失败\")\n            return False, filepath\n    except Exception as e:\n        print_error(f\"错误: {str(e)}\")\n        return False, None\n\n\ndef test_sample_txt():\n    \"\"\"测试 sample.txt 文件\"\"\"\n    print_header(\"测试 4: 处理 sample.txt\")\n    \n    sample_path = Path(\"backend/sample.txt\")\n    \n    if not sample_path.exists():\n        print_error(f\"sample.txt 不存在: {sample_path}\")\n        return False\n    \n    try:\n        # 读取原始文件\n        with open(sample_path, \"rb\") as f:\n            original_data = f.read()\n        print_info(f\"原始文件大小: {len(original_data)} 字节\")\n        \n        # 模拟 Huffman 编码（简化版）\n        # 实际的 Huffman 编码会更复杂\n        test_dir = Path(\"test_gzip\")\n        test_dir.mkdir(exist_ok=True)\n        \n        # 压缩\n        compressed = gzip.compress(original_data)\n        test_file = test_dir / \"sample_compressed.gz\"\n        with open(test_file, \"wb\") as f:\n            f.write(compressed)\n        \n        compressed_size = os.path.getsize(test_file)\n        compression_ratio = 100 - (compressed_size / len(original_data) * 100)\n        \n        print_success(f\"GZIP 压缩成功\")\n        print_info(f\"压缩后大小: {compressed_size} 字节\")\n        print_info(f\"压缩率: {compression_ratio:.2f}%\")\n        print_info(f\"测试文件保存到: {test_file}\")\n        \n        # 验证解压\n        with gzip.open(test_file, \"rb\") as f:\n            decompressed = f.read()\n        \n        if decompressed == original_data:\n            print_success(f\"解压验证: sample.txt 数据一致\")\n            return True\n        else:\n            print_error(f\"解压数据不匹配\")\n            return False\n    except Exception as e:\n        print_error(f\"错误: {str(e)}\")\n        return False\n\n\ndef test_compatibility():\n    \"\"\"测试标准工具兼容性\"\"\"\n    print_header(\"测试 5: 标准工具兼容性信息\")\n    \n    print_info(\"GZIP 格式兼容性\")\n    print_info(\"✅ 7-Zip 24.x 及更高版本\")\n    print_info(\"✅ WinRAR 6.x 及更高版本\")\n    print_info(\"✅ Linux gzip 命令\")\n    print_info(\"✅ Windows 内置解压工具\")\n    print_info(\"✅ Python gzip 模块\")\n    \n    print_info(\"\\n解压命令示例:\")\n    print_info(\"Linux:   gzip -d filename.gz\")\n    print_info(\"Windows: 7z x filename.gz\")\n    print_info(\"Python:  python -m gzip -d filename.gz\")\n    \n    return True\n\n\ndef cleanup_test_files():\n    \"\"\"清理测试文件\"\"\"\n    print_header(\"清理测试文件\")\n    \n    test_dir = Path(\"test_gzip\")\n    if test_dir.exists():\n        try:\n            import shutil\n            shutil.rmtree(test_dir)\n            print_success(f\"删除测试目录: {test_dir}\")\n        except Exception as e:\n            print_error(f\"无法删除测试目录: {str(e)}\")\n    else:\n        print_info(f\"测试目录不存在\")\n\n\ndef main():\n    \"\"\"主函数\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"  🔍 Huffman 压缩 - GZIP 格式验证脚本\")\n    print(\"  版本: 1.0\")\n    print(\"=\"*60)\n    \n    results = []\n    \n    # 运行所有测试\n    results.append((\"GZIP 压缩功能\", test_gzip_compress()))\n    results.append((\"Huffman + GZIP\", test_huffman_simulation()))\n    \n    success, filepath = test_file_operations()\n    results.append((\"文件操作\", success))\n    \n    results.append((\"sample.txt 处理\", test_sample_txt()))\n    results.append((\"工具兼容性\", test_compatibility()))\n    \n    # 打印测试总结\n    print_header(\"📊 测试总结\")\n    for test_name, passed in results:\n        status = \"✅ 通过\" if passed else \"❌ 失败\"\n        print(f\"{status}  {test_name}\")\n    \n    total = len(results)\n    passed = sum(1 for _, p in results if p)\n    print(f\"\\n总体: {passed}/{total} 测试通过\")\n    \n    if passed == total:\n        print_success(\"所有测试通过! GZIP 格式已准备好使用。\")\n    else:\n        print_error(f\"有 {total - passed} 个测试失败\")\n    \n    # 询问是否清理测试文件\n    print()\n    response = input(\"是否清理测试文件? (y/n): \").strip().lower()\n    if response == 'y':\n        cleanup_test_files()\n    else:\n        print_info(\"保留测试文件在 test_gzip/ 目录\")\n    \n    print(\"\\n\" + \"=\"*60)\n    print(\"  验证完成\")\n    print(\"=\"*60 + \"\\n\")\n\n\nif __name__ == \"__main__\":\n    main()\n